export const W=34,H=22;
export const terrain={wall:'#',floor:'.',water:'~',lava:'^',shrine:'+',exit:'>'};
export function rng(seed){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)}
export function makeWorld(seed=Date.now()){const r=rng(seed);const g=Array.from({length:H},(_,y)=>Array.from({length:W},(_,x)=>x==0||y==0||x==W-1||y==H-1?terrain.wall:terrain.wall));const rooms=[];for(let i=0;i<70;i++){const rw=4+(r()*7|0),rh=3+(r()*5|0),x=1+(r()*(W-rw-2)|0),y=1+(r()*(H-rh-2)|0);const room={x,y,w:rw,h:rh,cx:x+(rw/2|0),cy:y+(rh/2|0)};if(rooms.some(o=>x<o.x+o.w+1&&x+rw+1>o.x&&y<o.y+o.h+1&&y+rh+1>o.y))continue;for(let yy=y;yy<y+rh;yy++)for(let xx=x;xx<x+rw;xx++)g[yy][xx]=terrain.floor;if(rooms[0]){let a=rooms.at(-1),b=room;for(let xx=Math.min(a.cx,b.cx);xx<=Math.max(a.cx,b.cx);xx++)g[a.cy][xx]=terrain.floor;for(let yy=Math.min(a.cy,b.cy);yy<=Math.max(a.cy,b.cy);yy++)g[yy][b.cx]=terrain.floor}rooms.push(room)}
 const floors=[];g.forEach((row,y)=>row.forEach((c,x)=>c==terrain.floor&&floors.push({x,y})));const pick=()=>floors.splice(r()*floors.length|0,1)[0];for(let i=0;i<22;i++){const p=pick();g[p.y][p.x]=r()<.45?terrain.water:r()<.75?terrain.lava:terrain.shrine}const start=rooms[0]||{cx:2,cy:2},end=rooms.at(-1)||{cx:W-3,cy:H-3};g[end.cy][end.cx]=terrain.exit;const names=['骨爵','齿轮巫','孢子王','镜甲兽','星尘盗','熔岩母虫'];const enemies=Array.from({length:16},(_,i)=>{const p=pick();return{id:i,x:p.x,y:p.y,hp:8+(r()*14|0),max:22,dmg:2+(r()*5|0),name:names[i%names.length],elite:r()<.18}});const loot=Array.from({length:18},(_,i)=>{const p=pick();return{id:i,x:p.x,y:p.y,type:r()<.45?'药剂':r()<.75?'符文':'遗物',power:1+(r()*4|0)}});return{seed,grid:g,player:{x:start.cx,y:start.cy,hp:42,maxHp:42,atk:7,def:1,xp:0,level:1,turn:0,mode:'探索'},enemies,loot,log:['远古地牢重组完成：自动冒险开始。'],won:false,lost:false}}
export function passable(s,x,y){return s.grid[y]?.[x]&&s.grid[y][x]!=terrain.wall&&!s.enemies.some(e=>e.hp>0&&e.x==x&&e.y==y)}
const dirs=[[1,0],[-1,0],[0,1],[0,-1]];const dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);function stepToward(s,a,b){return dirs.map(([dx,dy])=>({x:a.x+dx,y:a.y+dy,d:Math.abs(a.x+dx-b.x)+Math.abs(a.y+dy-b.y)})).filter(p=>passable(s,p.x,p.y)).sort((m,n)=>m.d-n.d)[0]}
export function tick(old){const s=structuredClone(old);if(s.won||s.lost)return s;const p=s.player;p.turn++;const here=s.grid[p.y][p.x];if(here==terrain.lava)p.hp-=3;if(here==terrain.water)p.mode='涉水';if(here==terrain.shrine&&p.hp<p.maxHp){p.hp=Math.min(p.maxHp,p.hp+5);s.grid[p.y][p.x]=terrain.floor;s.log.unshift('圣坛回应，生命恢复。')}let item=s.loot.find(l=>l.x==p.x&&l.y==p.y);if(item){if(item.type=='药剂')p.hp=Math.min(p.maxHp,p.hp+10+item.power);if(item.type=='符文')p.atk+=item.power;if(item.type=='遗物'){p.def++;p.maxHp+=4;p.hp+=4}s.loot=s.loot.filter(l=>l.id!=item.id);s.log.unshift(`拾取${item.type} +${item.power}`)}let adj=s.enemies.find(e=>e.hp>0&&dist(e,p)==1);if(adj){const hit=Math.max(1,p.atk+(p.level-1)*2-adj.elite);adj.hp-=hit;s.log.unshift(`攻击${adj.elite?'精英':''}${adj.name}造成${hit}`);if(adj.hp<=0){p.xp+=adj.elite?7:3;s.log.unshift(`${adj.name}倒下。`);if(p.xp>=p.level*10){p.xp=0;p.level++;p.maxHp+=8;p.hp=p.maxHp;p.atk+=2;s.log.unshift(`升级到 ${p.level}！`)}}}else{const target=s.enemies.filter(e=>e.hp>0).sort((a,b)=>dist(a,p)-dist(b,p))[0]||{x:W-2,y:H-2};const goal=p.hp<18?s.loot.find(l=>l.type=='药剂')||target:target;const st=stepToward(s,p,goal);if(st){p.x=st.x;p.y=st.y;p.mode=goal.type?'补给':'猎杀'}}for(const e of s.enemies.filter(e=>e.hp>0)){if(dist(e,p)==1){const hurt=Math.max(1,e.dmg+(e.elite?3:0)-p.def);p.hp-=hurt;s.log.unshift(`${e.name}反击 ${hurt}`)}else if(dist(e,p)<8){const st=stepToward({...s,enemies:s.enemies.filter(x=>x.id!=e.id)},e,p);if(st){e.x=st.x;e.y=st.y}}}if(s.grid[p.y][p.x]==terrain.exit&&s.enemies.every(e=>e.hp<=0)){s.won=true;s.log.unshift('地牢核心净化，胜利！')}if(p.hp<=0){s.lost=true;s.log.unshift('英雄倒下，地牢吞噬了一切。')}s.log=s.log.slice(0,8);return s}
export function score(s){return s.player.level*100+s.player.xp*7+s.enemies.filter(e=>e.hp<=0).length*25+s.loot.length*-2+s.player.hp}
